const DAY_MS = 1000;
const START_YEAR = 1100;
const MONTH_NAMES = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
function isLeapYear(y) { return y % 4 === 0; }
function daysInMonth(y, monthIdx) {
  const lengths = [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return lengths[monthIdx];
}
function getCalendarDate(dayCount) {
  let remaining = dayCount - 1;
  let year = START_YEAR;
  while (true) {
    const daysInYear = isLeapYear(year) ? 366 : 365;
    if (remaining < daysInYear) break;
    remaining -= daysInYear;
    year++;
  }
  let month = 0;
  while (remaining >= daysInMonth(year, month)) {
    remaining -= daysInMonth(year, month);
    month++;
  }
  return { year, month, dayOfMonth: remaining + 1 };
}
function daysUntilYearEnd(dayCount) {
  const date = getCalendarDate(dayCount);
  let remaining = daysInMonth(date.year, date.month) - date.dayOfMonth;
  for (let m = date.month + 1; m < 12; m++) remaining += daysInMonth(date.year, m);
  return remaining;
}
// The inverse of getCalendarDate: turns a (year, 0-indexed month, day-of-month) into the
// same absolute day-count getCalendarDate would read back out of it. Used to schedule a
// Fehde attack for a specific future calendar date (e.g. "1. Juli des Folgejahres").
function dayCountForDate(year, monthIdx, dayOfMonth) {
  let count = 0;
  for (let y = START_YEAR; y < year; y++) count += isLeapYear(y) ? 366 : 365;
  for (let m = 0; m < monthIdx; m++) count += daysInMonth(year, m);
  return count + dayOfMonth;
}
