// be left standing undefended.
const KEEP_SIEGE_HP = 24;
const GATE_DAMAGE_PER_TICK = 0.3;
const RAM_DAMAGE_MULT = 2.6;
const CATAPULT_RANGE = 5.2;
const CATAPULT_DAMAGE_PER_TICK = 0.55;
const ARROW_STEP = 0.07;
const ARROW_ANIM_MS = 40;

// Siege equipment thresholds
const LADDER_YEAR = 3;
const RAM_YEAR = 5;
const CATAPULT_YEAR = 10;
// Act II brings sappers (Mineure), who dig under a wall until it caves in however strong it
