          treesIn.forEach((t) => { if (!t.felled && OWNED_REGIONS.has(t.region || 'kern')) { const d = distance({ i: w.curI, j: w.curJ }, { i: t.i, j: t.j }) / (t.rate || 1); if (d < bestD) { bestD = d; best = t; } } });
