  feldzug: { name: 'Feldzugserfahrung', icon: '🚩', text: 'Feldzüge kämpfen mit 25 % mehr Kraft.' },
  korn: { name: 'Kornkammer', icon: '🌾', text: 'Ernte +12 %.' },
